-- =============================================================================
-- 511 — LE CAHIER D'EXERCICES DE 2DE (partie 13)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 511 --niveau 2de --fichiers snt.n2,snt.n3,sport.n1 --suffixe 13 > supabase/contenu/511_exercices_2de_13.sql
--
-- 63 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   snt.n2                  30 exercices · 10 chapitres
--   snt.n3                  24 exercices · 8 chapitres
--   sport.n1                 9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('8ea815b3-95dd-5167-bf75-e5984fe9a394'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le lien du menu de la cantine","competence":"lire-tableau","situation":"Lina ouvre le site du lycée depuis son téléphone. Son navigateur garde la trace de chaque page demandée au serveur, avec le code de réponse reçu.","documents":[{"id":"journal","type":"tableau","titre":"Les quatre pages demandées par Lina","colonnes":["Page demandée","Code de réponse"],"lignes":[["/accueil.html","200"],["/ancienne-page.html","301"],["/menu-cantine.html","404"],["/inscription.html","500"]],"source":"Journal inventé pour l’exercice"}],"questions":[{"enonce":"Lina clique sur le lien du menu de la cantine. Touche le code qui montre que cette page est introuvable.","aide":"Cherche la ligne dont l’adresse est /menu-cantine.html, puis lis son code.","type":"zone","document":"journal","multiple":false},{"enonce":"Associe chaque code de réponse HTTP à sa signification.","aide":"Le 4 de 404 signale une demande qui ne mène à rien ; le 5 de 500 signale une panne chez le serveur.","type":"association","gauche":[{"id":"g0","texte":"200"},{"id":"g1","texte":"301"},{"id":"g2","texte":"404"},{"id":"g3","texte":"500"}],"droite":[{"id":"d0","texte":"Succès"},{"id":"d1","texte":"Erreur du serveur"},{"id":"d2","texte":"Introuvable"},{"id":"d3","texte":"Redirection"}]},{"enonce":"Sur ces quatre requêtes, combien ont reçu un code d’erreur (404 ou 500) ?","aide":"Relis la colonne des codes et ne garde que ceux de la liste de l’énoncé.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La page /menu-cantine.html reçoit le code **404** : le serveur répond qu’il ne trouve pas la ressource demandée."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**200** : succès ; **301** : redirection vers une autre adresse ; **404** : ressource introuvable ; **500** : erreur du serveur."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Le code 404 (page introuvable) et le code 500 (erreur du serveur) sont des erreurs : il y en a **2**. Le 301 est une redirection, pas une erreur."}]$ex$::jsonb),
  ('8ea815b3-95dd-5167-bf75-e5984fe9a394'::uuid, 2, 2, 10, 35, 4,
