  ('dcb3c715-962c-5aca-bb37-37235e8ad924'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le courriel de la fausse banque","competence":"analyser-document","situation":"Aïcha reçoit un courriel qui dit venir de sa banque. Avant de cliquer, elle compare le message avec l’adresse officielle du site de sa banque.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Courriel reçu par Aïcha","auteur":"Courriel écrit pour l’exercice","blocs":["Objet : Votre compte sera bloqué","Cher client, une activité suspecte a été détectée. Confirmez vos identifiants immédiatement pour éviter le blocage.","Lien : http://mabanque-verification.example/connexion"]},{"id":"officiel","type":"tableau","titre":"Ce que dit la carte bancaire d’Aïcha","colonnes":["Information","Valeur"],"lignes":[["Site officiel de la banque","https://www.mabanque.example"],["Moyen d’authentification","Double authentification activée"]],"source":"Données inventées pour l’exercice"}],"questions":[{"enonce":"De quelle menace ce courriel est-il un exemple ?","aide":"Le message imite un site de confiance pour obtenir quelque chose de l’élève.","type":"choix","options":[{"id":"a","texte":"Le wifi public non chiffré"},{"id":"b","texte":"Le hameçonnage"},{"id":"c","texte":"Le rançongiciel"},{"id":"d","texte":"Le cookie tiers"}],"multiple":false},{"enonce":"Touche le mot qui cherche à te mettre la pression pour te faire agir sans réfléchir.","aide":"Cherche un adverbe qui veut dire « tout de suite ».","type":"zone","document":"mail","multiple":false},{"enonce":"En comparant avec l’adresse officielle de la banque, touche l’adresse du lien qui ne vient pas d’elle.","aide":"Compare le nom de domaine du lien avec « www.mabanque.example » dans le second document.","type":"zone","document":"mail","multiple":true},{"enonce":"Range chaque geste : bon réflexe, ou geste à éviter ?","aide":"Un bon réflexe vérifie avant d’agir et limite les dégâts d’une fuite.","type":"categories","categories":[{"id":"c0","texte":"Bon réflexe"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Saisir ses identifiants après avoir cliqué sur le lien du courriel"},{"id":"i1","texte":"Taper soi-même l’adresse officielle de la banque"},{"id":"i2","texte":"Activer la double authentification"},{"id":"i3","texte":"Utiliser le même mot de passe pour la banque et pour un jeu"},{"id":"i4","texte":"Vérifier l’adresse exacte et le cadenas HTTPS avant de saisir un mot de passe"}]}]}$ex$::jsonb,
