  ('51bdc90b-47ca-5ffd-a3b9-f2a538abada5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi tout le monde reste sur la même messagerie","competence":"modeliser","situation":"Dans la classe d’Anaïs, tous les élèves veulent discuter par messages. Plus il y a d’élèves inscrits sur une même messagerie, plus chacun peut parler à de monde : c’est un effet de réseau.","documents":[{"id":"regle","type":"texte","genre":"article","titre":"Le nombre de conversations possibles","auteur":"Texte écrit pour l’exercice","blocs":["Chaque utilisateur peut écrire à chacun des autres, et une conversation relie deux personnes.","Pour n utilisateurs, le nombre de conversations à deux possibles est n × (n − 1) ÷ 2."]},{"id":"graph","type":"graphique","forme":"barres","titre":"Conversations possibles selon le nombre d’utilisateurs","categories":["2","4","8","16"],"series":[{"nom":"Conversations","valeurs":[1,6,28,120],"teinte":"turquoise"}],"axeY":{"titre":"Conversations à deux","min":0,"max":120,"pas":20},"axeX":{"titre":"Nombre d’utilisateurs"},"valeurs":true,"source":"Calculé avec la formule du texte"}],"questions":[{"enonce":"Combien de conversations à deux sont possibles entre 10 utilisateurs ?","aide":"Calcule 10 × 9, puis divise par 2.","type":"nombre"},{"enonce":"Quand on passe de 8 à 16 utilisateurs, par combien le nombre de conversations est-il à peu près multiplié ? (arrondi à l’unité)","aide":"Divise la valeur de la barre 16 par celle de la barre 8, puis arrondis.","type":"nombre"},{"enonce":"Quelle conséquence économique cet effet de réseau favorise-t-il ?","aide":"Si la valeur d’un service croît avec le nombre d’utilisateurs, partir coûte de plus en plus cher.","type":"choix","options":[{"id":"a","texte":"La concentration en quelques très grands acteurs"},{"id":"b","texte":"La gratuité de tous les services"},{"id":"c","texte":"Une multiplication de petits services équivalents"},{"id":"d","texte":"La disparition des grandes plateformes"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Pense à ce qui retient Anaïs sur la messagerie de ses amis.","type":"trous","segments":["Plus il y a d’utilisateurs, plus la valeur du service ",0," ; il devient alors coûteux de ",1,"."],"banque":["diminue","augmente","partir","rester"]}]}$ex$::jsonb,
