   $ex$[{"cle":{"type":"nombre","valeur":38,"tolerance":0},"affichage":"38 µg/m³","explication":"(31 + 45) ÷ 2 = **38** µg/m³."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Seules les valeurs 45 et 52 dépassent 40 : **2** mesures. La valeur 40 est égale au seuil, pas supérieure."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La **licence** autorise la réutilisation libre, y compris commerciale, à condition de citer la source."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une donnée ouverte peut être réutilisée à des fins commerciales ; ici, la licence demande de **citer la source**."}]$ex$::jsonb),
