tre publié tel quel, ou pas ?","aide":"Les données personnelles et celles couvertes par un secret ne s’ouvrent pas sans protection.","type":"categories","categories":[{"id":"c0","texte":"Publiable tel quel"},{"id":"c1","texte":"Pas tel quel"}],"items":[{"id":"i0","texte":"Les résultats d’une élection, commune par commune"},{"id":"i1","texte":"Le fichier nominatif des patients d’un hôpital"},{"id":"i2","texte":"Les prix des carburants"},{"id":"i3","texte":"Des statistiques couvertes par le secret statistique"},{"id":"i4","texte":"Les horaires des bus"}]}]}$ex$::jsonb,
