44,"arrondi":4,"teinte":"jaune","motif":"clair","texte":"Alim.","id":"z8","zone":true},{"forme":"texte","x":349,"y":208,"texte":"redondante","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[280,82],"a":[306,82],"teinte":"gris","epaisseur":3},{"forme":"ligne","de":[280,172],"a":[306,172],"teinte":"gris","epaisseur":3}]},{"id":"copies","type":"tableau","titre":"Copies d’un même fichier d’élève","colonnes":["Site","Nombre de copies"],"lignes":[["Site de Lyon",3],["Site de Lille",2]],"source":"Exemple inventé pour l’exercice"}],"questions":[{"enonce":"Touche l’élément qui évacue la chaleur produite par les serveurs.","aide":"Les flèches dessinées envoient de l’air frais vers les baies.","type":"zone","document":"dc","multiple":false},{"enonce":"Touche les deux éléments qui permettent de continuer à fonctionner pendant une coupure de courant.","aide":"Un élément produit de l’électricité sur place ; l’autre double les arrivées de courant.","type":"zone","document":"dc","multiple":true},{"enonce":"Un incendie détruit tout le site de Lyon. Combien de copies du fichier restent-elles ?","aide":"Retire du total les copies qui se trouvaient dans le site détruit.","type":"nombre"},{"enonce":"Pourquoi répliquer les données sur plusieurs machines et plusieurs sites ?","aide":"Pense à ce qui arrive aux données si un seul disque ou un seul bâtiment est touché.","type":"choix","options":[{"id":"a","texte":"Pour réduire le nombre de serveurs nécessaires"},{"id":"b","texte":"Pour survivre à une panne matérielle ou à un sinistre"},{"id":"c","texte":"Pour supprimer toute dépendance à la connexion"},{"id":"d","texte":"Pour que la facture d’électricité baisse"}],"multiple":false}]}$ex$::jsonb,
