:"nombre"},{"enonce":"Associe chaque terme de vocabulaire des graphes à sa définition.","aide":"La distance ne retient que la plus courte des chaînes possibles.","type":"association","gauche":[{"id":"g0","texte":"Degré d’un sommet"},{"id":"g1","texte":"Chaîne"},{"id":"g2","texte":"Distance entre deux sommets"},{"id":"g3","texte":"Diamètre"}],"droite":[{"id":"d0","texte":"La plus grande de ces distances"},{"id":"d1","texte":"La longueur de la plus courte chaîne"},{"id":"d2","texte":"Le nombre de ses voisins"},{"id":"d3","texte":"Une suite d’arêtes reliant deux sommets"}]}]}$ex$::jsonb,
