":[94,60],"a":[146,60],"fleche":"fin","teinte":"gris","epaisseur":2},{"forme":"ligne","de":[214,60],"a":[266,60],"fleche":"deux","teinte":"gris","epaisseur":2},{"forme":"cercle","cx":60,"cy":60,"r":30,"texte":"Noé","teinte":"turquoise","motif":"clair","id":"z8","zone":true},{"forme":"cercle","cx":180,"cy":60,"r":30,"texte":"Camille","teinte":"turquoise","motif":"clair","id":"z9","zone":true},{"forme":"cercle","cx":300,"cy":60,"r":30,"texte":"Yan","teinte":"turquoise","motif":"clair","id":"z10","zone":true}]}],"questions":[{"enonce":"Quelle est la distance entre Ana et Gaël ? (la longueur de la plus courte chaîne)","aide":"Cherche la plus courte suite d’arêtes de Ana à Gaël, en passant par Bilal.","type":"nombre"},{"enonce":"Touche tous les voisins de Bilal.","aide":"Un voisin est relié à Bilal par une arête, sans intermédiaire.","type":"zone","document":"reseau","multiple":true},{"enonce":"Quel est le diamètre de ce graphe, c’est-à-dire la plus grande des distances entre deux sommets ?","aide":"Cherche les deux personnes les plus éloignées : l’une est à une extrémité du graphe, l’autre à l’autre bout.","type":"nombre"},{"enonce":"Touche le compte que personne ne suit.","aide":"Dans un graphe orienté, cherche le sommet où aucune flèche n’arrive.","type":"zone","document":"suivis","multiple":false},{"enonce":"Pourquoi un graphe orienté est-il nécessaire pour ce second réseau ?","aide":"Regarde les flèches entre Noé et Camille : y en a-t-il dans les deux sens ?","type":"choix","options":[{"id":"a","texte":"Parce qu’il ne contient aucune chaîne"},{"id":"b","texte":"Parce que tous les comptes ont le même nombre de voisins"},{"id":"c","texte":"Parce que je peux te suivre sans que tu me suives"},{"id":"d","texte":"Parce que la distance y est toujours égale à 1"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"La plus courte chaîne est Ana – Bilal – Farid – Gaël : **3** arêtes. L’autre chemin, par Chloé et David, est plus long."},{"cle":{"type":"zone","ids":["z1","z3","z5"]},"explication":"Bilal est directement relié à **Ana, Chloé et Farid** : son degré est 3."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Ana et Eva sont les plus éloignées : Ana – Bilal – Chloé – David – Eva, soit **4** arêtes. Aucune autre paire n’est plus éloignée."},{"cle":{"type":"zone","ids":["z8"]},"explication":"Aucune flèche n’arrive sur **Noé** : il suit Camille, mais personne ne le suit."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une arête simple dit « amis ». Une flèche dit « **je te suis sans que tu me suives** » : c’est ce qu’exprime un graphe orienté."}]$ex$::jsonb),
  ('ed70a8c4-8a56-5978-a4aa-665810b5c881'::uuid, 3, 3, 15, 50, 5,
