epaisseur":2},{"forme":"ligne","de":[130,60],"a":[250,60],"teinte":"gris","epaisseur":2},{"forme":"cercle","cx":50,"cy":60,"r":13,"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":130,"cy":60,"r":13,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":50,"cy":150,"r":13,"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":130,"cy":150,"r":13,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":250,"cy":60,"r":13,"teinte":"violet","motif":"plein","id":"z5","zone":true},{"forme":"cercle","cx":330,"cy":60,"r":13,"teinte":"violet","motif":"plein","id":"z6","zone":true},{"forme":"cercle","cx":250,"cy":150,"r":13,"teinte":"violet","motif":"plein","id":"z7","zone":true},{"forme":"cercle","cx":330,"cy":150,"r":13,"teinte":"violet","motif":"plein","id":"z8","zone":true}]}],"questions":[{"enonce":"Combien de lettres sont arrivées à destination au total ?","aide":"Additionne la hauteur de toutes les barres.","type":"nombre"},{"enonce":"Touche le nombre d’intermédiaires le plus fréquent.","aide":"Cherche la barre la plus haute.","type":"zone","document":"resultats","multiple":false},{"enonce":"Calcule le nombre moyen d’intermédiaires et donne-le arrondi à l’unité.","aide":"Multiplie chaque nombre d’intermédiaires par le nombre de lettres, additionne, puis divise par 30.","type":"nombre"},{"enonce":"Touche les deux personnes reliées par le lien faible, celui qui raccourcit le plus les chemins entre les deux groupes.","aide":"Dans chaque groupe, tout le monde se connaît ; cherche le seul trait qui sort d’un groupe pour aller dans l’autre.","type":"zone","document":"groupes","multiple":true},{"enonce":"Dans chaque groupe, tout le monde est relié à tout le monde. Que révèle cette forte densité de triangles ?","aide":"Un triangle, ce sont trois personnes qui se connaissent deux à deux.","type":"choix","options":[{"id":"a","texte":"Mes amis sont souvent amis entre eux"},{"id":"b","texte":"Aucun lien ne raccourcit les chemins"},{"id":"c","texte":"La distance moyenne est très grande"},{"id":"d","texte":"Les liens faibles sont les plus nombreux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30","explication":"1 + 3 + 6 + 8 + 7 + 4 + 1 = **30** lettres."},{"cle":{"type":"zone","ids":["k3"]},"explication":"La barre la plus haute, 8 lettres, correspond à **6 intermédiaires**, comme dans l’expérience de Milgram."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"(3×1 + 4×3 + 5×6 + 6×8 + 7×7 + 8×4 + 9×1) ÷ 30 = 183 ÷ 30 = 6,1, soit environ **6** : les fameux six degrés de séparation."},{"cle":{"type":"zone","ids":["z2","z5"]},"explication":"Le trait unique entre les deux groupes relie ces **deux sommets** : un lien faible, vers une connaissance lointaine, qui relie deux mondes séparés."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une forte densité de triangles signifie que **mes amis sont souvent amis entre eux** : c’est un trait des réseaux sociaux, avec une distance moyenne faible."}]$ex$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le fil d’actualité de Nour","competence":"lire-tableau","situation":"Nour ouvre son application. Les publications s’affichent dans un certain ordre, qu’elle n’a pas choisi. Elle compare l’ordre du fil avec l’heure de publication.","documents":[{"id":"fil","type":"tableau","titre":"Les cinq premières publications du fil de Nour","colonnes":["Position","Publication","Publiée"],"lignes":[["1","Match de foot du week-end","il y a 9 h"],["2","Vidéo de chat","il y a 2 jours"],["3","Annonce du club de musique","il y a 20 min"],["4","Recette de crêpes","il y a 3 h"],["5","Clip d’un chanteur","il y a 1 h"]],"source":"Fil inventé pour l’exercice"}],"questions":[{"enonce":"Touche l’heure de la publication la plus récente.","aide":"La plus récente est celle publiée il y a le moins de temps.","type":"zone","document":"fil","multiple":false},{"enonce":"Combien de publications datent de plus de 3 heures ?","aide":"Une publication d’il y a exactement 3 heures n’est pas « de plus de 3 heures ».","type":"nombre"},{"enonce":"Pourquoi le fil de Nour n’est-il pas classé par ordre chronologique ?","aide":"L’application cherche à faire durer le temps passé et les interactions de Nour.","type":"choix","options":[{"id":"a","texte":"Un algorithme le classe selon ce qui retiendra Nour"},{"id":"b","texte":"Les serveurs mélangent les heures de publication des posts"},{"id":"c","texte":"Le fil montre toujours d’abord les publications les plus anciennes"},{"id":"d","texte":"Les publications sont classées au hasard par l’application"}],"multiple":false},{"enonce":"Associe chaque mécanisme de recommandation à ce qu’il utilise.","aide":"Le filtrage collaboratif s’appuie sur d’autres utilisateurs, pas seulement sur Nour.","type":"association","gauche":[{"id":"g0","texte":"Classement du fil"},{"id":"g1","texte":"Prédiction de réaction"},{"id":"g2","texte":"Filtrage collaboratif"}],"droite":[{"id":"d0","texte":"Tes clics, le temps passé, tes interactions"},{"id":"d1","texte":"Il n’est pas chronologique"},{"id":"d2","texte":"Les comportements d’utilisateurs semblables"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"L’annonce du club a été publiée **il y a 20 minutes** : c’est la plus récente, et pourtant elle est en position 3."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Le match (9 h) et la vidéo de chat (2 jours) : **2** publications. La recette est à 3 h pile, pas au-delà."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le fil est **classé par un algorithme** qui prédit la réaction de Nour (clics, temps passé, interactions), pas par l’heure."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **classement** n’est pas chronologique ; la **prédiction** s’appuie sur clics, temps passé et interactions ; le **filtrage collaboratif** sur des utilisateurs jugés semblables."}]$ex$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quel film proposer à Zack ?","competence":"raisonner","situation":"Une plateforme de films veut recommander un titre à Zack. Elle compare ses goûts à ceux de trois autres élèves, puis propose ce qu’ont aimé ceux qui lui ressemblent : c’est le filtrage collaboratif.","documents":[{"id":"gouts","type":"tableau","titre":"Les films aimés (oui) ou non","colonnes":["Élève","Les Ailes","Tempête","Bambou","Zénith"],"lignes":[["Inès","oui","oui","oui","non"],["Hugo","oui","non","non","oui"],["Mia","non","oui","oui","non"],["Zack","oui","oui","non","non"]],"source":"Goûts inventés pour l’exercice"}],"questions":[{"enonce":"Touche l’élève dont les goûts ressemblent le plus à ceux de Zack.","aide":"Compte, pour chaque élève, les films qu’il aime comme Zack.","type":"zone","document":"gouts","multiple":false},{"enonce":"Combien de films Zack et Inès aiment-ils tous les deux ?","aide":"Cherche les colonnes où les deux lignes affichent « oui ».","type":"nombre"},{"enonce":"Quel film la plateforme recommandera-t-elle à Zack, qui ne l’a pas aimé ?","aide":"Propose un film que des élèves proches de Zack aiment et que Zack n’a pas encore aimé.","type":"choix","options":[{"id":"a","texte":"Les Ailes"},{"id":"b","texte":"Zénith"},{"id":"c","texte":"Bambou"},{"id":"d","texte":"Tempête"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Ce n’est ni la vérité ni l’équilibre qui sont visés.","type":"trous","segments":["Un algorithme de recommandation cherche à maximiser l’",0,", c’est-à-dire le temps et l’",1," que l’utilisateur donne."],"banque":["engagement","information","vérité","attention"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"Inès aime comme Zack **deux films** (Les Ailes et Tempête) ; Hugo et Mia n’en ont qu’un en commun avec lui."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Les Ailes et Tempête : **2** films aimés par les deux."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Bambou** est aimé par Inès et Mia, deux élèves proches de Zack. Zénith n’est aimé que par Hugo, le moins proche."},{"cle":{"type":"trous","trous":[["engagement"],["attention"]]},"affichage":"engagement · attention","explication":"L’objectif optimisé est l’**engagement** : le temps et l’**attention**. Un algorithme qui maximise l’engagement optimise la réaction."}]$ex$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La photo de la digue qui a déjà sept ans","competence":"analyser-document","situation":"Rayan reçoit une publication qui montre une digue effondrée et lui demande de la partager. Avant de le faire, il fait une recherche d’image inversée pour savoir d’où vient la photo.","documents":[{"id":"post","type":"texte","genre":"article","titre":"La publication reçue","auteur":"Texte écrit pour l’exercice","blocs":["Publié par le compte « InfosVite »","CHOC : la digue du port s’est effondrée hier ! Des dizaines de blessés ! Partagez avant qu’on supprime la photo !"]},{"id":"inverse","type":"tableau","titre":"Résultats de la recherche d’image inversée","colonnes":["Où la photo apparaît","Date","Contexte"],"lignes":[["Compte « InfosVite »","hier","Digue « effondrée », sans source"],["Blog météo","il y a 3 jours","Reprend la même photo"],["Banque d’images Rivage","12 mars 2019","Tempête dans un autre pays, jetée détruite"],["Forum local","il y a 2 jours","Reprend la même photo"]],"source":"Résultats inventés pour l’exercice"}],"questions":[{"enonce":"Touche la date de la première publication de la photo.","aide":"La plus ancienne date est celle de la source d’origine.","type":"zone","document":"inverse","multiple":false},{"enonce":"Que peut conclure Rayan ?","aide":"Compare la date de la photo avec celle de l’événement annoncé.","type":"choix","options":[{"id":"a","texte":"La photo est authentique puisque plusieurs sites la reprennent"},{"id":"b","texte":"La photo montre bien l’événement d’hier"},{"id":"c","texte":"La photo est trop floue pour être vérifiée"},{"id":"d","texte":"La photo est ancienne et a été détournée pour illustrer une autre histoire"}],"multiple":false},{"enonce":"Touche le mot qui cherche à provoquer une émotion forte pour faire partager la publication.","aide":"Cherche le mot écrit pour surprendre dès la première ligne.","type":"zone","document":"post","multiple":false},{"enonce":"Associe chaque facteur de désinformation à son effet.","aide":"Le facteur de répétition tient dans le nombre de fois où l’on voit une information.","type":"association","gauche":[{"id":"g0","texte":"Biais de confirmation"},{"id":"g1","texte":"Effet de répétition"},{"id":"g2","texte":"Illusion de familiarité"},{"id":"g3","texte":"Surprise et indignation"}],"droite":[{"id":"d0","texte":"Ce qu’on lit souvent paraît vrai"},{"id":"d1","texte":"Ce qui est connu paraît fiable"},{"id":"d2","texte":"L’infox circule plus vite que le vrai"},{"id":"d3","texte":"On retient ce qui nous donne raison"}]},{"enonce":"Range chaque geste : est-ce un réflexe de vérification ?","aide":"Un réflexe de vérification cherche d’où vient l’information avant de la relayer.","type":"categories","categories":[{"id":"c0","texte":"Réflexe de vérification"},{"id":"c1","texte":"Pas une vérification"}],"items":[{"id":"i0","texte":"Croire l’information parce qu’on l’a vue cent fois"},{"id":"i1","texte":"Partager vite pour prévenir ses amis"},{"id":"i2","texte":"Chercher la même information ailleurs"},{"id":"i3","texte":"Chercher la source et sa date"},{"id":"i4","texte":"Faire une recherche d’image inversée"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La photo apparaît dès le **12 mars 2019**, bien avant la publication reçue : c’est elle, l’origine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une photo de 2019, prise dans un autre pays, ne peut pas montrer un événement d’hier : elle est **détournée**. Que plusieurs sites la reprennent ne la rend pas vraie."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**CHOC** joue sur la surprise : l’indignation est le levier utilisé pour faire circuler une infox plus vite qu’une information vérifiée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Le **biais de confirmation** fait retenir ce qui nous donne raison ; la **répétition** rend vrai ; la **familiarité** rend fiable ; la **surprise** fait circuler l’infox."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Source et date, image inversée et recoupement sont des **vérifications**. Partager vite ou croire parce que c’est répété n’en sont pas."}]$ex$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les traces de Yanis pendant une journée","competence":"lire-tableau","situation":"Yanis ne pense pas laisser de traces : « Je ne poste presque rien ! » Pourtant, au fil de la journée, son identité numérique s’enrichit de choses qu’il n’a pas toutes choisies.","documents":[{"id":"journee","type":"tableau","titre":"La journée de Yanis","colonnes":["Heure","Ce qui se passe"],"lignes":[["8 h","Yanis publie une photo de son petit-déjeuner"],["12 h","Il regarde une vidéo ; la plateforme note la durée de lecture"],["15 h","Sa cousine publie une photo où elle le cite et l’identifie"],["18 h","Il écrit un avis sur un jeu vidéo"],["21 h","Son téléphone envoie sa position à une application météo"]],"source":"Journée inventée pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui est une trace héritée, laissée par quelqu’un d’autre à propos de Yanis.","aide":"Cherche l’événement où ce n’est pas Yanis qui publie.","type":"zone","document":"journee","multiple":false},{"enonce":"Combien de traces volontaires, publiées par Yanis lui-même, la journée contient-elle ?","aide":"Compte les événements où Yanis écrit ou publie quelque chose de son plein gré.","type":"nombre"},{"enonce":"Range chaque exemple selon le type de trace.","aide":"Volontaire : tu publies. Involontaire : la machine enregistre. Héritée : d’autres écrivent sur toi.","type":"categories","categories":[{"id":"c0","texte":"Volontaire"},{"id":"c1","texte":"Involontaire"},{"id":"c2","texte":"Héritée"}],"items":[{"id":"i0","texte":"Une photo où un ami t’a identifié"},{"id":"i1","texte":"L’adresse IP de ton téléphone"},{"id":"i2","texte":"L’identifiant de ton appareil"},{"id":"i3","texte":"Un message que tu envoies à un ami"},{"id":"i4","texte":"Un commentaire d’un camarade qui te cite"},{"id":"i5","texte":"Un avis que tu écris sur un site"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La photo publiée par sa cousine, qui l’identifie, est une **trace héritée** : Yanis n’en est pas l’auteur."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"La photo de 8 h et l’avis de 18 h sont des traces **volontaires** : **2**."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c1","i3":"c0","i4":"c2","i5":"c0"}},"explication":"**Volontaire** : message, avis. **Involontaire** : adresse IP, identifiant d’appareil. **Héritée** : commentaire qui te cite, photo où l’on t’identifie."}]$ex$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Clara veut reprendre la main sur ses données","competence":"analyser-document","situation":"Clara, 17 ans, se rend compte qu’une application garde beaucoup d’informations sur elle. Elle écrit à la plateforme cinq demandes différentes. Chacune correspond à un droit donné par le RGPD, en vigueur depuis 2018.","documents":[{"id":"demandes","type":"tableau","titre":"Les cinq demandes de Clara","colonnes":["Demande","Ce que Clara écrit"],"lignes":[["a","Je veux savoir quelles données vous avez sur moi."],["b","Mon nom est mal orthographié dans mon profil, corrigez-le."],["c","Supprimez mon compte et mes données."],["d","Je veux récupérer mes photos pour les transférer vers une autre application."],["e","Je refuse que mes données servent à de la publicité ciblée."]],"source":"Messages inventés pour l’exercice"}],"questions":[{"enonce":"Touche la demande qui exerce le droit à la portabilité.","aide":"Ce droit permet de récupérer ses données pour les transférer ailleurs.","type":"zone","document":"demandes","multiple":false},{"enonce":"Associe chaque droit à la demande de Clara qui l’exerce.","aide":"Accéder, rectifier, effacer et s’opposer : repère le verbe de chaque demande.","type":"association","gauche":[{"id":"g0","texte":"Droit d’accès"},{"id":"g1","texte":"Droit de rectification"},{"id":"g2","texte":"Droit à l’effacement"},{"id":"g3","texte":"Droit d’opposition"}],"droite":[{"id":"d0","texte":"Mon nom est mal orthographié, corrigez-le"},{"id":"d1","texte":"Je refuse la publicité ciblée"},{"id":"d2","texte":"Supprimez mon compte et mes données"},{"id":"d3","texte":"Je veux savoir quelles données vous avez sur moi"}]},{"enonce":"Quelle autorité française contrôle le respect des données personnelles et sanctionne ? Écris son sigle.","aide":"Son sigle a quatre lettres et commence par « Commission nationale ».","type":"texte"},{"enonce":"Clara obtient la suppression de son compte. Qu’advient-il d’une photo d’elle qu’un ami avait recopiée sur son propre site ?","aide":"Le compte est celui de Clara ; la copie appartient au site de l’ami.","type":"choix","options":[{"id":"a","texte":"Elle disparaît automatiquement de tous les sites du Web"},{"id":"b","texte":"Elle devient privée sur le site de son ami"},{"id":"c","texte":"Elle subsiste sur le site de l’ami, qui l’a copiée"},{"id":"d","texte":"Elle est remplacée par une photo très floue"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"La demande **d** veut récupérer ses photos et les transférer : c’est la **portabilité**."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**Accès** : savoir ce qui est collecté ; **rectification** : corriger une erreur ; **effacement** (droit à l’oubli) : supprimer ; **opposition** : refuser un traitement."},{"cle":{"type":"texte","acceptes":["cnil","la cnil"]},"affichage":"CNIL","explication":"C’est la **CNIL** (Commission nationale de l’informatique et des libertés) : elle contrôle et sanctionne."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un compte supprimé ne fait pas disparaître ce qui a déjà été copié ou archivé : la photo **subsiste** ailleurs."}]$ex$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ce que le recruteur trouve sur Samir","competence":"raisonner","situation":"Samir, 17 ans, cherche un stage. Le recruteur tape son nom dans un moteur de recherche. Samir est surpris : il ne se souvenait pas de certains résultats, et certains ne viennent pas de lui.","documents":[{"id":"resultats","type":"tableau","titre":"Résultats trouvés en cherchant « Samir Haddad »","colonnes":["Résultat","Publié par","Année"],"lignes":[["Photo de soirée où Samir est identifié","Léo, un ami",2021],["Avis sur un jeu vidéo","Samir",2022],["Fiche du club de basket avec sa photo","Le club",2023],["Commentaire moqueur sous une vidéo, signé Samir","Samir",2020]],"source":"Résultats inventés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Samir","emoji":"🧑","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Samir","texte":"Ta photo de 2021 est ressortie dans une recherche !"},{"qui":"Léo","texte":"Mais c’est vieux, personne ne la verra jamais."}]}],"questions":[{"enonce":"Combien de résultats ont été publiés par une autre personne ou un autre organisme que Samir ?","aide":"Regarde la colonne « Publié par » : garde ce qui n’est pas Samir.","type":"nombre"},{"enonce":"Touche la publication la plus ancienne, qui illustre le mieux le risque de résurgence.","aide":"La résurgence concerne une vieille publication qui ressort hors de son contexte ; cherche l’année la plus petite.","type":"zone","document":"resultats","multiple":false},{"enonce":"Pourquoi Léo a-t-il tort de dire que personne ne verra jamais la photo ?","aide":"Publier, c’est écrire à ceux que l’on vise, à ceux qu’on n’a pas prévus et à ceux qui liront dans dix ans.","type":"choix","options":[{"id":"a","texte":"Elle peut ressurgir des années plus tard, hors contexte"},{"id":"b","texte":"Les moteurs de recherche ignorent les photos de soirée"},{"id":"c","texte":"Une photo disparaît toujours au bout d’un an environ"},{"id":"d","texte":"Seul l’auteur de la photo peut encore la retrouver"}],"multiple":false},{"enonce":"Associe chaque risque à sa description.","aide":"Chaque risque a un mot qui le résume : « ressurgir », « harceler », « usurper », « consentir ».","type":"association","gauche":[{"id":"g0","texte":"Résurgence"},{"id":"g1","texte":"Cyberharcèlement"},{"id":"g2","texte":"Usurpation d’identité"},{"id":"g3","texte":"Image diffusée sans consentement"}],"droite":[{"id":"d0","texte":"Une publication ancienne ressort hors de son contexte"},{"id":"d1","texte":"Se faire passer pour quelqu’un d’autre"},{"id":"d2","texte":"Montrer la photo de quelqu’un sans son accord"},{"id":"d3","texte":"Des messages répétés pour nuire à une personne"}]},{"enonce":"Range chaque geste : bonne pratique, ou pratique risquée ?","aide":"Une bonne pratique limite ce qui est vu et respecte l’image des autres.","type":"categories","categories":[{"id":"c0","texte":"Bonne pratique"},{"id":"c1","texte":"Pratique risquée"}],"items":[{"id":"i0","texte":"Utiliser le même profil pour tout"},{"id":"i1","texte":"Séparer ses usages personnel, scolaire et professionnel"},{"id":"i2","texte":"Poster la photo d’un camarade sans lui demander"},{"id":"i3","texte":"Signaler un contenu illicite à la plateforme"},{"id":"i4","texte":"Régler les paramètres de confidentialité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"La photo de Léo et la fiche du club : **2** traces héritées, que Samir n’a pas publiées."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le commentaire de **2020** est le plus ancien : écrit des années plus tôt, il ressort aujourd’hui, hors de son contexte, au moment d’un recrutement."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est la **résurgence** : une publication recopiée ou archivée peut ressortir des années plus tard, lors d’un recrutement par exemple."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"La **résurgence** fait ressortir le passé ; le **cyberharcèlement**, l’**usurpation d’identité** et la diffusion d’images sans consentement sont des délits."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Sont de **bonnes pratiques** : régler la confidentialité, séparer les usages, signaler les contenus illicites. Poster l’image d’autrui sans accord ou tout mélanger est risqué."}]$ex$::jsonb),
  ('099e65eb-373f-5b5b-b745-3d1651a8782a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le T en pixel art de Nina","competence":"observer-schema","situation":"Nina dessine la lettre T en pixel art sur une grille de 5 lignes et 5 colonnes. Chaque case est un pixel : l’ordinateur le code par des nombres.","documents":[{"id":"grille","type":"schema","titre":"Le T de Nina (chaque carré est un pixel)","largeur":260,"hauteur":210,"source":"Dessin écrit pour l’exercice","elements":[{"forme":"rect","x":40,"y":20,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":76,"y":20,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":112,"y":20,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":148,"y":20,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"rect","x":184,"y":20,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z5","zone":true},{"forme":"rect","x":40,"y":56,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z6","zone":true},{"forme":"rect","x":76,"y":56,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z7","zone":true},{"forme":"rect","x":112,"y":56,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z8","zone":true},{"forme":"rect","x":148,"y":56,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z9","zone":true},{"forme":"rect","x":184,"y":56,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z10","zone":true},{"forme":"rect","x":40,"y":92,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z11","zone":true},{"forme":"rect","x":76,"y":92,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z12","zone":true},{"forme":"rect","x":112,"y":92,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z13","zone":true},{"forme":"rect","x":148,"y":92,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z14","zone":true},{"forme":"rect","x":184,"y":92,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z15","zone":true},{"forme":"rect","x":40,"y":128,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z16","zone":true},{"forme":"rect","x":76,"y":128,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z17","zone":true},{"forme":"rect","x":112,"y":128,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z18","zone":true},{"forme":"rect","x":148,"y":128,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z19","zone":true},{"forme":"rect","x":184,"y":128,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z20","zone":true},{"forme":"rect","x":40,"y":164,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z21","zone":true},{"forme":"rect","x":76,"y":164,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z22","zone":true},{"forme":"rect","x":112,"y":164,"l":34,"h":34,"arrondi":2,"teinte":"violet","motif":"plein","id":"z23","zone":true},{"forme":"rect","x":148,"y":164,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z24","zone":true},{"forme":"rect","x":184,"y":164,"l":34,"h":34,"arrondi":2,"teinte":"gris","motif":"clair","id":"z25","zone":true}]}],"questions":[{"enonce":"Combien de pixels colorés contient la lettre T ?","aide":"Compte les 5 pixels de la ligne du haut, puis ceux de la barre verticale en dessous.","type":"nombre"},{"enonce":"Touche le pixel coloré tout en bas de la barre du T.","aide":"Descends jusqu’à la dernière ligne, au milieu.","type":"zone","document":"grille","multiple":false},{"enonce":"Associe chaque couleur à ses composantes (rouge, vert, bleu) sur 8 bits.","aide":"Le noir est l’absence de lumière ; le blanc est le maximum de toutes les composantes.","type":"association","gauche":[{"id":"g0","texte":"Noir"},{"id":"g1","texte":"Blanc"},{"id":"g2","texte":"Rouge vif"}],"droite":[{"id":"d0","texte":"(255, 0, 0)"},{"id":"d1","texte":"(255, 255, 255)"},{"id":"d2","texte":"(0, 0, 0)"}]},{"enonce":"Complète le codage d’un pixel couleur.","aide":"Le pixel a trois composantes de même taille.","type":"trous","segments":["Chaque composante est codée sur ",0," bits, soit ",1," niveaux ; un pixel couleur pèse donc ",2," bits."],"banque":["16","24","8","3","256"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"5 pixels en haut et 4 pixels dans la barre : 5 + 4 = **9** pixels colorés."},{"cle":{"type":"zone","ids":["z23"]},"explication":"C’est le pixel de la **5e ligne et de la 3e colonne** : le pied du T."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Noir** : toutes les composantes à 0 ; **blanc** : toutes à 255 ; **rouge vif** : rouge au maximum, vert et bleu à 0."},{"cle":{"type":"trous","trous":[["8"],["256"],["24"]]},"affichage":"8 · 256 · 24","explication":"**8** bits donnent **256** niveaux ; trois composantes pèsent 3 × 8 = **24** bits, soit environ 16,7 millions de couleurs."}]$ex$::jsonb),
  ('099e65eb-373f-5b5b-b745-3d1651a8782a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La photo prise avec le téléphone","competence":"analyser-document","situation":"Léna prend une photo avec son téléphone et la publie. Elle ne sait pas que le fichier garde des informations cachées. Elle s’étonne aussi de son poids : l’image a pourtant beaucoup de pixels.","documents":[{"id":"exif","type":"tableau","titre":"Les propriétés du fichier de la photo","colonnes":["Propriété","Valeur"],"lignes":[["Appareil","Phone Z2"],["Date","12/09/2026, 16 h 41"],["Définition","4 000 × 3 000 pixels"],["Codage","24 bits par pixel (RVB)"],["Format","JPEG"],["Poids du fichier","5,2 Mo"],["Position GPS","48,86 N ; 2,35 E"]],"source":"Fichier inventé pour l’exercice"},{"id":"positions","type":"tableau","titre":"Coordonnées de trois lieux repérés sur la carte","colonnes":["Lieu","Latitude (N)","Longitude"],"lignes":[["A","48,86","2,35 E"],["B","45,76","4,84 E"],["C","44,84","0,58 O"]],"source":"Coordonnées arrondies"},{"id":"carte","type":"carte","titre":"Trois lieux de France","fond":"france","lieux":[{"id":"z1","lieu":"paris","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"lyon","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"bordeaux","symbole":"lettre","lettre":"C","teinte":"corail"}]}],"questions":[{"enonce":"Combien de pixels contient cette photo ?","aide":"Multiplie le nombre de colonnes par le nombre de lignes de pixels.","type":"nombre","unite":"pixels"},{"enonce":"Quel serait le poids brut de l’image, sans compression, en Mo ? (1 Mo = 1 000 000 octets, un pixel de 24 bits pèse 3 octets)","aide":"Multiplie le nombre de pixels par 3 octets, puis passe en millions d’octets.","type":"nombre","unite":"Mo"},{"enonce":"Pourquoi le fichier ne pèse-t-il que 5,2 Mo alors que le poids brut est de 36 Mo ?","aide":"Regarde la ligne « Format » du tableau.","type":"choix","options":[{"id":"a","texte":"Le format JPEG compresse avec perte d’information"},{"id":"b","texte":"Le format JPEG supprime la moitié des pixels"},{"id":"c","texte":"Le poids brut ne tient pas compte des pixels"},{"id":"d","texte":"La photo est en niveaux de gris"}],"multiple":false},{"enonce":"La photo porte une position GPS cachée. Touche sur la carte le lieu où elle a été prise.","aide":"Compare la position GPS du fichier avec les coordonnées des trois lieux du second tableau, puis repère la lettre.","type":"zone","document":"carte","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":12000000,"tolerance":0},"affichage":"12 000 000 pixels","explication":"4 000 × 3 000 = **12 000 000** pixels, soit 12 millions."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 Mo","explication":"12 000 000 × 3 = 36 000 000 octets, soit **36 Mo**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **JPEG** utilise une compression avec perte : il réduit fortement le poids, au prix d’une perte d’information (des artefacts si l’on compresse trop)."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La position GPS 48,86 N ; 2,35 E correspond au lieu **A**, le plus au nord des trois. Les métadonnées EXIF révèlent donc où Léna se trouvait."}]$ex$::jsonb),
