  ('a1e01900-f3b8-5864-854f-a929df5e7796'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le portrait de grand-mère passe au gris","competence":"lire-tableau","situation":"Samia numérise une vieille photo de sa grand-mère. Pour la passer en niveaux de gris, son logiciel a relevé trois pixels : chacun est noté par ses trois composantes rouge, verte et bleue (R, V, B), de 0 à 255.","documents":[{"id":"pixels","type":"tableau","titre":"Trois pixels de la photo","colonnes":["Pixel","R","V","B"],"lignes":[["P1",240,240,210],["P2",200,100,60],["P3",30,45,60]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Avec la méthode de la moyenne, quel niveau de gris obtient le pixel P2 ?","aide":"Additionne les trois composantes de la ligne P2, puis divise par 3.","type":"nombre"},{"enonce":"Touche la ligne du pixel qui sera le plus sombre une fois passé en gris par la méthode de la moyenne.","aide":"Plus les trois composantes sont petites, plus la moyenne est basse.","type":"zone","document":"pixels","multiple":false},{"enonce":"Complète le négatif du pixel P3 : on remplace chaque composante par 255 moins sa valeur.","aide":"Calcule 255 − 30, puis 255 − 45, puis 255 − 60.","type":"trous","segments":["Le négatif de P3 est (",0,", ",1,", ",2,")."]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120","explication":"Moyenne de P2 : (200 + 100 + 60) / 3 = 360 / 3 = **120**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"P3 vaut (30 + 45 + 60) / 3 = **45** : c’est le gris le plus sombre. P1 donne 230 et P2 120."},{"cle":{"type":"trous","trous":[["225"],["210"],["195"]]},"affichage":"225 · 210 · 195","explication":"Le négatif de (30, 45, 60) est (255 − 30, 255 − 45, 255 − 60) = (**225, 210, 195**)."}]$ex$::jsonb),
  ('a1e01900-f3b8-5864-854f-a929df5e7796'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le petit filtre de Lucas, ligne par ligne","competence":"programmer","situation":"Lucas apprend Python en classe de SNT. Il écrit un programme qui calcule, pour un pixel de sa photo de vacances, un niveau de gris, un négatif et un résultat en noir et blanc.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Le programme de Lucas","auteur":"Programme écrit pour l’exercice","blocs":["pixel = (200, 100, 60)","moyenne = (pixel[0] + pixel[1] + pixel[2]) // 3","negatif = (255 - pixel[0], 255 - pixel[1], 255 - pixel[2])","seuil = 128","noir_ou_blanc = 255 if moyenne > seuil else 0","print(moyenne, negatif[0], noir_ou_blanc)"]}],"questions":[{"enonce":"Quelle valeur la variable moyenne contient-elle à la fin du programme ?","aide":"L’opérateur // est la division entière : 360 // 3.","type":"nombre"},{"enonce":"Parmi les trois valeurs affichées par la dernière ligne, quelle est la deuxième, celle de negatif[0] ?","aide":"negatif[0] est la première composante du négatif : 255 moins la composante rouge du pixel.","type":"nombre"},{"enonce":"Que vaut noir_ou_blanc quand le programme s’arrête ?","aide":"Compare la moyenne au seuil : la condition moyenne > seuil est-elle vraie ?","type":"choix","options":[{"id":"a","texte":"0, le pixel devient noir"},{"id":"b","texte":"255, le pixel devient blanc"},{"id":"c","texte":"128, le pixel reste gris"},{"id":"d","texte":"120, la valeur de la moyenne"}],"multiple":false},{"enonce":"Touche la valeur qui fixe la limite entre noir et blanc.","aide":"Cette limite porte un nom précis dans le cours : le seuil.","type":"zone","document":"prog","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120","explication":"moyenne = (200 + 100 + 60) // 3 = 360 // 3 = **120**."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55","explication":"negatif[0] = 255 − pixel[0] = 255 − 200 = **55**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La moyenne vaut 120, et 120 n’est pas supérieur au seuil 128 : la condition est fausse, le pixel devient **noir (0)**."},{"cle":{"type":"zone","ids":["m23"]},"explication":"Le **seuil** vaut 128 : au-dessus, le pixel devient blanc ; en dessous, noir."}]$ex$::jsonb),
