   $ex${"titre":"La photo de plage prise en soirée","competence":"lire-graphique","situation":"Noé a photographié la plage au coucher du soleil, et l’image paraît très sombre. Son logiciel affiche l’histogramme de la photo : le nombre de pixels pour chaque tranche de valeurs, de 0 (noir) à 255 (blanc).","documents":[{"id":"hist","type":"graphique","forme":"barres","titre":"Histogramme de la photo de Noé","categories":["0 à 63","64 à 127","128 à 191","192 à 255"],"series":[{"nom":"Pixels","valeurs":[60,25,10,5],"teinte":"violet"}],"axeY":{"titre":"Nombre de pixels","unite":"en milliers","min":0,"max":70,"pas":10},"axeX":{"titre":"Valeur du pixel"},"valeurs":false,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche la tranche de valeurs qui contient le plus de pixels.","aide":"Cherche la barre la plus haute.","type":"zone","document":"hist","multiple":false},{"enonce":"Que dit cet histogramme tassé à gauche de la photo de Noé ?","aide":"À gauche de l’axe, ce sont les valeurs proches de 0 : sombres ou claires ?","type":"choix","options":[{"id":"a","texte":"Elle est sous-exposée"},{"id":"b","texte":"Elle est surexposée"},{"id":"c","texte":"Elle est bien exposée"},{"id":"d","texte":"Elle manque de couleurs"}],"multiple":false},{"enonce":"Combien de pixels, en milliers, ont une valeur de 128 ou plus ?","aide":"Additionne les deux tranches de droite. Le graphique compte en milliers.","type":"nombre","unite":"milliers"}]}$ex$::jsonb,
