   $ex${"titre":"Téléphone ou appareil hybride : qui capte le mieux ?","competence":"analyser-document","situation":"Yanis hésite entre filmer ses concerts avec son téléphone ou avec un appareil hybride. Il compare les capteurs. Pour comparer, il utilise cette équivalence : une surface de 1 mm² répartie sur 1 million de photosites donne 1 µm² par photosite.","documents":[{"id":"capteurs","type":"tableau","titre":"Deux capteurs","colonnes":["Appareil","Mégapixels","Dimensions du capteur (mm)","Surface du capteur (mm²)"],"lignes":[["Téléphone",12,"6,4 × 4,8","30,72"],["Appareil hybride",24,"36 × 24",864]],"enteteLignes":true,"source":"Chiffres écrits pour l’exercice"},{"id":"notice","type":"fiche","modele":"ticket","entete":"Fiche technique du téléphone","sousTitre":"Texte écrit pour l’exercice","emoji":"📱","lignes":[{"texte":"Capteur","valeur":"12 mégapixels"},{"texte":"Format brut (RAW)","valeur":"14 bits par composante","id":"z1"},{"texte":"Mode nuit","valeur":"plusieurs images assemblées"}],"teinte":"violet"}],"questions":[{"enonce":"Quelle est la surface d’un photosite de l’appareil hybride, en µm² ?","aide":"Divise 864 mm² par 24 millions de photosites.","type":"nombre","unite":"µm²"},{"enonce":"Quelle est la surface d’un photosite du téléphone, en µm² ?","aide":"Divise 30,72 mm² par 12 millions de photosites.","type":"nombre","unite":"µm²"},{"enonce":"Arrondi à l’unité, combien de fois la surface d’un photosite de l’appareil hybride dépasse-t-elle celle du téléphone ?","aide":"Divise 36 par 2,56.","type":"nombre"},{"enonce":"Les deux photos sont prises à haute sensibilité. Laquelle contiendra le moins de bruit, toutes choses égales par ailleurs ?","aide":"Des photosites plus grands recueillent plus de lumière avant de la convertir.","type":"choix","options":[{"id":"a","texte":"Aucune : la sensibilité n’a pas d’effet sur le bruit"},{"id":"b","texte":"Celle du téléphone, qui a un plus petit capteur"},{"id":"c","texte":"Celle du téléphone, qui a moins de mégapixels"},{"id":"d","texte":"Celle de l’appareil hybride, aux photosites plus grands"}],"multiple":false},{"enonce":"Combien de niveaux le format RAW du téléphone peut-il distinguer pour une composante ?","aide":"Lis le nombre de bits dans la fiche technique : il y a 2 puissance n niveaux.","type":"nombre","unite":"niveaux"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 µm²","explication":"864 / 24 = **36 µm²** par photosite."},{"cle":{"type":"nombre","valeur":2.56,"tolerance":0.01},"affichage":"2,56 µm²","explication":"30,72 / 12 = **2,56 µm²** par photosite."},{"cle":{"type":"nombre","valeur":14,"tolerance":0.4},"affichage":"14","explication":"36 / 2,56 ≈ 14,06, soit environ **14 fois** plus grande : un photosite recueille plus de lumière."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **taille des photosites** compte plus que les mégapixels : montée en sensibilité = bruit, d’autant plus marqué que les photosites sont petits."},{"cle":{"type":"nombre","valeur":16384,"tolerance":0},"affichage":"16 384 niveaux","explication":"2 puissance 14 = **16 384** niveaux par composante, contre 256 sur 8 bits."}]$ex$::jsonb),
  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Comment le téléphone de Léa sait où elle est","competence":"observer-schema","situation":"Léa marche vers le lycée et son téléphone affiche sa position sur la carte. Le schéma montre les signaux reçus à cet instant : les flèches indiquent le sens de circulation des signaux.","documents":[{"id":"sat","type":"schema","titre":"Des satellites et un téléphone","largeur":320,"hauteur":250,"elements":[{"forme":"ligne","de":[60,62],"a":[150,168],"style":"pointilles","fleche":"fin","teinte":"violet"},{"forme":"ligne","de":[160,54],"a":[160,164],"style":"pointilles","fleche":"fin","teinte":"violet"},{"forme":"ligne","de":[260,66],"a":[172,168],"style":"pointilles","fleche":"fin","teinte":"violet"},{"forme":"emoji","x":60,"y":44,"emoji":"🛰️","taille":36,"id":"z1","zone":true},{"forme":"emoji","x":160,"y":38,"emoji":"🛰️","taille":36,"id":"z2","zone":true},{"forme":"emoji","x":260,"y":48,"emoji":"🛰️","taille":36,"id":"z3","zone":true},{"forme":"emoji","x":160,"y":188,"emoji":"📱","taille":36,"id":"z4","zone":true},{"forme":"ligne","de":[20,214],"a":[300,214],"teinte":"brun"},{"forme":"texte","x":160,"y":236,"texte":"Le sol","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma simplifié écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’objet qui reçoit des signaux sans en envoyer aux satellites.","aide":"Suis les flèches : où arrivent-elles toutes ?","type":"zone","document":"sat","multiple":false},{"enonce":"Le schéma montre 3 satellites. Combien en faut-il au minimum pour obtenir la position et l’altitude ?","aide":"Trois satellites donnent deux points ; il en faut un de plus pour corriger l’horloge du récepteur.","type":"nombre","unite":"satellites"},{"enonce":"Associe chaque système de positionnement à son origine.","aide":"Galileo est le système européen.","type":"association","gauche":[{"id":"g0","texte":"GPS"},{"id":"g1","texte":"Galileo"},{"id":"g2","texte":"GLONASS"},{"id":"g3","texte":"Beidou"}],"droite":[{"id":"d0","texte":"Chine"},{"id":"d1","texte":"États-Unis"},{"id":"d2","texte":"Union européenne"},{"id":"d3","texte":"Russie"}]}]}$ex$::jsonb,
