  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le temps de vol des signaux","competence":"calculer","situation":"Le récepteur de Mehdi mesure le temps mis par le signal de chaque satellite pour lui parvenir. Le signal voyage à la vitesse de la lumière : 300 000 km par seconde.","documents":[{"id":"vol","type":"tableau","titre":"Délais mesurés","colonnes":["Satellite","Délai du signal (s)","Distance (km)"],"lignes":[["A","0,070","?"],["B","0,075",22500],["C","0,068","?"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice, vitesse arrondie à 300 000 km/s"}],"questions":[{"enonce":"À quelle distance du récepteur se trouve le satellite A, en kilomètres ?","aide":"Distance = vitesse × durée : 300 000 × 0,070.","type":"nombre","unite":"km"},{"enonce":"À quelle distance du récepteur se trouve le satellite C, en kilomètres ?","aide":"Même calcul avec le délai de la ligne C.","type":"nombre","unite":"km"},{"enonce":"Touche le satellite le plus proche du récepteur.","aide":"Le signal le plus court à parvenir vient du satellite le plus proche.","type":"zone","document":"vol","multiple":false},{"enonce":"L’horloge du récepteur se trompe d’une microseconde (0,000001 s). De combien de mètres la distance calculée est-elle fausse ?","aide":"Multiplie 300 000 km/s, soit 300 000 000 m/s, par 0,000001 s.","type":"nombre","unite":"m"}]}$ex$::jsonb,
