  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La randonnée de Zoé et son application météo","competence":"analyser-document","situation":"Zoé part en randonnée avec l’application « Rando Météo ». Son téléphone passe d’une plaine dégagée à une rue étroite, puis à un tunnel. Avant de partir, elle lit aussi l’autorisation que l’application lui demande.","documents":[{"id":"lieux","type":"tableau","titre":"Ce que reçoit le téléphone de Zoé","colonnes":["Lieu","Satellites reçus","Précision de la position"],"lignes":[["Plaine dégagée",9,"3 m"],["Rue étroite en ville",5,"25 m"],["Tunnel",0,"Aucune position"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"permission","type":"fiche","modele":"ticket","entete":"Rando Météo","sousTitre":"Autorisation demandée","emoji":"🥾","lignes":[{"texte":"Position","valeur":"précise, en permanence","id":"z1"},{"texte":"Utilité","valeur":"afficher la météo du lieu"},{"texte":"Envoyée à","valeur":"un serveur de l’éditeur"}],"pied":"Fiche écrite pour l’exercice","teinte":"vert"}],"questions":[{"enonce":"Associe le nombre de satellites reçus à ce qu’il détermine.","aide":"Chaque satellite ajoute une contrainte : une sphère, puis son intersection avec une autre sphère…","type":"association","gauche":[{"id":"g0","texte":"1 satellite"},{"id":"g1","texte":"2 satellites"},{"id":"g2","texte":"3 satellites"},{"id":"g3","texte":"4 satellites"}],"droite":[{"id":"d0","texte":"Deux points possibles"},{"id":"d1","texte":"Une sphère de positions"},{"id":"d2","texte":"Un cercle de positions"},{"id":"d3","texte":"La position et l’altitude"}]},{"enonce":"Touche l’endroit où le téléphone ne peut pas calculer de position avec les seuls satellites.","aide":"Il faut au moins quatre satellites pour une position complète.","type":"zone","document":"lieux","multiple":false},{"enonce":"Dans la rue étroite, le téléphone reçoit 5 satellites mais la précision tombe à 25 m. Pourquoi ?","aide":"Pense au chemin que parcourt un signal qui rebondit sur un mur.","type":"choix","options":[{"id":"a","texte":"L’horloge des satellites se dérègle"},{"id":"b","texte":"Le téléphone émet vers les satellites"},{"id":"c","texte":"Les satellites s’éteignent en ville"},{"id":"d","texte":"Les signaux se réfléchissent sur les façades"}],"multiple":false},{"enonce":"Dans le tunnel, quel appoint permet de garder une position entre deux points connus ?","aide":"Quels capteurs du téléphone mesurent le mouvement ?","type":"choix","options":[{"id":"a","texte":"Un cinquième satellite caché dans le tunnel"},{"id":"b","texte":"L’horloge atomique du téléphone"},{"id":"c","texte":"La résolution de l’écran"},{"id":"d","texte":"Les capteurs internes : accéléromètre, gyroscope"}],"multiple":false},{"enonce":"Que peut faire Zoé de l’autorisation demandée par l’application ?","aide":"La position révèle domicile, habitudes et déplacements.","type":"choix","options":[{"id":"a","texte":"L’accepter en permanence, car c’est plus pratique pour elle"},{"id":"b","texte":"L’accepter sans lire, puisque la météo l’exige vraiment"},{"id":"c","texte":"Limiter la position à l’usage réel, pendant l’utilisation"},{"id":"d","texte":"Donner aussi son identifiant en plus de sa position précise"}],"multiple":false}]}$ex$::jsonb,
